{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Picroside-II, an iridoid glycoside closely analogous to loganin, was reported to rapidly penetrate the BBB and be detected in rat brain after systemic administration, directly supporting meaningful CNS access for this structural class despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Isovitexin, a polar C-glucosylated flavonoid, was quantified in rat brain and cerebellum after i.v. administration and labeled BBB-permeable, demonstrating that hydrophilic glycosides can achieve CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Guanosine, a polar nucleoside, entered the CNS within minutes and raised CSF concentrations after oral dosing via transporter-mediated uptake at the BBB, showing that transporter-mediated processes can provide meaningful CNS access for hydrophilic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Vidarabine (ara-A) achieved mean CSF-to-plasma ratios of 35% in patients, providing direct human evidence that polar glycoside-like nucleosides can have adequate CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Hydroxysafflor yellow A, a very polar bis-glycoside, reached 1026 ng/g in rat brain and was classified as BBB-permeable, reinforcing that high polarity does not preclude meaningful brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: despite an unfavorable passive-diffusion physicochemical prior, high-transfer experimental evidence from iridoid glycosides and other polar glycosides/nucleosides demonstrates meaningful CNS access after systemic administration; loganin shares the iridoid glycoside scaffold with picroside-II and similar polar/transporter-mediated exposure characteristics.",
  "evidence_gaps": [
    "No direct pharmacokinetic brain or CSF measurement for loganin itself in the provided evidence.",
    "Most analogue readouts are qualitative or single-timepoint; quantitative unbound brain-to-plasma ratios are lacking.",
    "The exact uptake/efflux transporter profile of loganin at the BBB is not established, so the mechanism of transfer is inferred from analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

